-- Courriels et SMS en anglais pour les personnes qui ont choisi l'anglais sur leur profil (demande d'Octa, 2026-11-25).
-- 1. Traductions dans une table à part : les 16 autres fonctions qui lisent comms.email_templates ne voient rien de nouveau.
-- 2. comms.langue_destinataire : 'en' si le courriel ou le téléphone du destinataire appartient à un locataire, un propriétaire
--    (ou copropriétaire) ou un contact dont la langue est 'en'; sinon 'fr'. vars.langue l'emporte s'il est fourni.
-- 3. comms.preparer_lot rend la version anglaise quand elle existe; les avis juridiques restent en français (Charte de la langue
--    française : à valider avec l'avocate avant de les traduire). Sans traduction : français, comme avant.
-- Le cadre du courriel (pied, désabonnement, « Répondez STOP ») et le format des montants et des dates suivent dans _shared/gabarits.ts.

create table if not exists comms.traductions_gabarits (
  code text not null,
  locale text not null check (locale in ('en')),
  name text,
  subject text,
  preheader text,
  sms_text text,
  contenu jsonb not null,
  updated_at timestamptz not null default now(),
  primary key (code, locale)
);
alter table comms.traductions_gabarits enable row level security;
drop policy if exists traductions_gabarits_lecture on comms.traductions_gabarits;
create policy traductions_gabarits_lecture on comms.traductions_gabarits for select to authenticated using (crm.can('studio.lire'));

create or replace function comms.langue_destinataire(p_canal text, p_adresse text) returns text
language sql stable security definer set search_path = '' as $$
  with a as (select lower(trim(coalesce(p_adresse, ''))) as courriel, right(regexp_replace(coalesce(p_adresse, ''), '\D', '', 'g'), 10) as tel)
  select case when exists (
      select 1 from a, public.tenants t where t.language = 'en'
        and case when p_canal = 'sms' then a.tel <> '' and right(regexp_replace(coalesce(t.phone, ''), '\D', '', 'g'), 10) = a.tel else lower(t.email) = a.courriel end
    union all
      select 1 from a, public.owners o left join public.users u on u.id = o.user_id where o.language = 'en'
        and case when p_canal = 'sms' then a.tel <> '' and right(regexp_replace(coalesce(o.phone, ''), '\D', '', 'g'), 10) = a.tel else a.courriel in (lower(o.email), lower(u.email)) end
    union all
      select 1 from a, public.owner_members m join public.owners o on o.id = m.owner_id join public.users u on u.id = m.user_id
        where o.language = 'en' and m.removed_at is null and p_canal <> 'sms' and lower(u.email) = a.courriel
    union all
      select 1 from a, crm.contacts c where c.language = 'en'
        and case when p_canal = 'sms' then a.tel <> '' and exists (select 1 from unnest(c.phones_e164) p where right(regexp_replace(p, '\D', '', 'g'), 10) = a.tel)
                 else exists (select 1 from unnest(c.emails) e where lower(e) = a.courriel) end
  ) then 'en' else 'fr' end
$$;
revoke all on function comms.langue_destinataire(text, text) from public, anon, authenticated;

create or replace function comms.preparer_lot(p_taille int default 50) returns setof jsonb
language plpgsql security definer set search_path = '' as $$
declare o comms.outbox; t comms.email_templates; v_coupe boolean; v_seq comms.sequence_enrollments; v_fen timestamptz;
        v_lang text; v_tr comms.traductions_gabarits; v_contenu jsonb; v_sms text; v_loc text;
begin
  select active into v_coupe from config.kill_switch;
  for o in select * from comms.outbox
           where status in ('queued', 'held_window', 'held_kill_switch') and scheduled_for <= now()
           order by scheduled_for limit p_taille for update skip locked
  loop
    select * into t from comms.email_templates where code = o.template_code and locale = 'fr' and active order by version desc limit 1;
    if not found then
      update comms.outbox set status = 'cancelled', last_error = 'gabarit inactif', updated_at = now() where id = o.id; continue;
    end if;
    -- 1. Coupe-circuit (sauf essentiels)
    if v_coupe and not t.essential then
      update comms.outbox set status = 'held_kill_switch', updated_at = now() where id = o.id and status <> 'held_kill_switch'; continue;
    end if;
    -- 2. Fenêtre (sauf essentiels)
    v_fen := comms.prochaine_fenetre(now(), t.window_start, t.window_end, t.business_days_only, t.essential);
    if v_fen > now() then
      update comms.outbox set status = 'held_window', scheduled_for = v_fen, updated_at = now() where id = o.id; continue;
    end if;
    -- 3. Suppression (STOP, désabonnement, rebond, plainte)
    if exists (select 1 from comms.suppressions s where s.channel = o.channel and lower(s.address) = lower(o.recipient)) then
      update comms.outbox set status = 'cancelled', last_error = 'suppression', updated_at = now() where id = o.id;
      perform crm.journal('comms.cancelled', 'comms.outbox', o.id, null, jsonb_build_object('raison', 'suppression'), 'send', 'cron', null, 'system');
      continue;
    end if;
    -- 4. Commercial : consentement LCAP valide pour ce canal
    if t.lcap_category = 'commercial' and not exists (
         select 1 from comms.consents c where c.channel = o.channel and lower(c.address) = lower(o.recipient)
           and c.withdrawn_at is null and (c.expires_at is null or c.expires_at > now())) then
      update comms.outbox set status = 'cancelled', last_error = 'consentement absent', updated_at = now() where id = o.id;
      perform crm.journal('comms.cancelled', 'comms.outbox', o.id, null, jsonb_build_object('raison', 'consentement'), 'send', 'cron', null, 'system');
      continue;
    end if;
    -- 5. Séquence arrêtée (réponse, STOP, maximum)
    if o.sequence_enrollment_id is not null then
      select * into v_seq from comms.sequence_enrollments where id = o.sequence_enrollment_id;
      if v_seq.stopped_at is not null then
        update comms.outbox set status = 'cancelled', last_error = 'sequence ' || v_seq.stopped_reason, updated_at = now() where id = o.id; continue;
      end if;
    end if;
    -- 6. Langue du destinataire (2026-11-25) : anglais si la personne l'a choisi et que le gabarit est traduit;
    --    les avis juridiques (lcap_category = 'legal') restent en français.
    v_contenu := t.contenu; v_sms := t.sms_text; v_loc := 'fr';
    v_lang := coalesce(nullif(o.vars ->> 'langue', ''), comms.langue_destinataire(o.channel, o.recipient));
    if v_lang = 'en' and t.lcap_category is distinct from 'legal' then
      select * into v_tr from comms.traductions_gabarits where code = t.code and locale = 'en';
      if found then v_contenu := v_tr.contenu; v_sms := coalesce(v_tr.sms_text, t.sms_text); v_loc := 'en'; end if;
    end if;
    update comms.outbox set status = 'sending', attempts = attempts + 1, updated_at = now() where id = o.id;
    return next jsonb_build_object('id', o.id, 'channel', o.channel, 'recipient', o.recipient, 'vars', o.vars, 'template_code', o.template_code,
      'contenu', v_contenu, 'sms_text', v_sms, 'locale', v_loc,
      'unsubscribe_required', t.unsubscribe_required, 'attempts', o.attempts + 1);
  end loop;
end $$;


